%dw 2.0
var resumeData = readUrl("classpath://data/resume-data.json", "application/json")
output application/json
---
{
    data: resumeData.profile,
    meta: {
        section: "profile",
        retrievedAt: now() as String {format: "yyyy-MM-dd'T'HH:mm:ss"}
    }
}

%dw 2.0
var resumeData = readUrl("classpath://data/resume-data.json", "application/json")
output application/json
---
{
    data: resumeData.experience,
    meta: {
        section: "experience",
        totalCompanies: sizeOf(resumeData.experience),
        retrievedAt: now() as String {format: "yyyy-MM-dd'T'HH:mm:ss"}
    }
}

%dw 2.0
var resumeData = readUrl("classpath://data/resume-data.json", "application/json")
var companyFilter = vars.companyFilter default ""
var filtered = resumeData.experience filter (exp) ->
    lower(exp.company) contains lower(companyFilter)
output application/json
---
if (sizeOf(filtered) > 0)
{
    data: filtered,
    meta: {
        section: "experience",
        filter: companyFilter,
        resultsFound: sizeOf(filtered),
        retrievedAt: now() as String {format: "yyyy-MM-dd'T'HH:mm:ss"}
    }
}
else
{
    error: "No experience found for company: " ++ companyFilter,
    availableCompanies: resumeData.experience.company,
    suggestion: "Try: v4 impact, deloitte, infosys, apisero, or accenture"
}

