%dw 2.0
var resumeData = readUrl("classpath://data/resume-data.json", "application/json")
var certs = resumeData.certifications
output application/json
---
{
    data: certs,
    summary: {
        totalCertifications: sizeOf(certs),
        byCategory: (certs groupBy (cert) -> cert.category)
            mapObject ((certGroup, category) -> {
                (category as String): sizeOf(certGroup)
            })
    },
    meta: {
        section: "certifications",
        retrievedAt: now() as String {format: "yyyy-MM-dd'T'HH:mm:ss"}
    }
}

%dw 2.0
var resumeData = readUrl("classpath://data/resume-data.json", "application/json")
var projects = resumeData.experience flatMap (exp) ->
    exp.clients map (client) -> {
        company: exp.company,
        role: exp.role,
        clientName: client.clientName,
        project: client.project,
        period: client.period,
        description: client.description,
        keyAchievements: client.keyAchievements,
        technologies: client.technologies
    }
output application/json
---
{
    data: projects,
    meta: {
        section: "projects",
        totalProjects: sizeOf(projects),
        retrievedAt: now() as String {format: "yyyy-MM-dd'T'HH:mm:ss"}
    }
}

%dw 2.0
var resumeData = readUrl("classpath://data/resume-data.json", "application/json")
output application/json
---
{
    data: resumeData.achievements,
    interests: resumeData.interests,
    meta: {
        section: "achievements",
        totalAwards: sizeOf(resumeData.achievements),
        retrievedAt: now() as String {format: "yyyy-MM-dd'T'HH:mm:ss"}
    }
}

%dw 2.0
var resumeData = readUrl("classpath://data/resume-data.json", "application/json")
var keyword = payload.keyword default ""
var kw = lower(keyword)

fun anyContains(arr, k) = !isEmpty(arr filter (item) -> lower(item default "") contains k)

var matchedExperience = resumeData.experience flatMap (exp) ->
    (exp.clients filter (client) ->
        (lower(client.description default "") contains kw) or
        (lower(client.project default "") contains kw) or
        (lower(client.clientName default "") contains kw) or
        anyContains(client.technologies default [], kw) or
        anyContains(client.keyAchievements default [], kw)
    ) map (client) -> {
        section: "experience",
        company: exp.company,
        role: exp.role,
        clientName: client.clientName,
        project: client.project,
        period: client.period,
        matchedIn: "experience"
    }

var skillMatches = {
    competencies: resumeData.skills.competencies filter (s) -> lower(s) contains kw,
    integrationPlatforms: resumeData.skills.integrationPlatforms filter (s) -> lower(s) contains kw,
    apiSecurity: resumeData.skills.apiSecurity filter (s) -> lower(s) contains kw,
    cloudAndInfrastructure: resumeData.skills.cloudAndInfrastructure filter (s) -> lower(s) contains kw,
    devopsAndCICD: resumeData.skills.devopsAndCICD filter (s) -> lower(s) contains kw,
    toolsAndPlatforms: resumeData.skills.toolsAndPlatforms filter (s) -> lower(s) contains kw,
    integrationPatterns: resumeData.skills.integrationPatterns filter (s) -> lower(s) contains kw
} mapObject ((value, key) -> {
    (key): value
}) filterObject (value) -> !isEmpty(value)

var matchedCerts = resumeData.certifications filter (cert) ->
    (lower(cert.name default "") contains kw) or
    (lower(cert.issuer default "") contains kw) or
    (lower(cert.category default "") contains kw)

var matchedAchievements = resumeData.achievements filter (ach) ->
    (lower(ach.award default "") contains kw) or
    (lower(ach.project default "") contains kw)

var profileMatch =
    (lower(resumeData.profile.summary default "") contains kw) or
    anyContains(resumeData.profile.highlights default [], kw)

output application/json
---
if (isEmpty(kw))
{
    error: "Please provide a keyword in the request body",
    example: { keyword: "MuleSoft" }
}
else
{
    keyword: keyword,
    results: {
        profileMatch: profileMatch,
        experience: matchedExperience,
        skills: skillMatches,
        certifications: matchedCerts,
        achievements: matchedAchievements
    },
    summary: {
        totalExperienceMatches: sizeOf(matchedExperience),
        totalCertificationMatches: sizeOf(matchedCerts),
        totalAchievementMatches: sizeOf(matchedAchievements),
        profileSummaryMatch: profileMatch
    },
    meta: {
        section: "search",
        keyword: keyword,
        retrievedAt: now() as String {format: "yyyy-MM-dd'T'HH:mm:ss"}
    }
}
